// Builds the parser fixtures deterministically: nasty spreadsheets (fixtures/xlsx), delimited text
// (fixtures/csv) and documents (fixtures/docs). The expected outputs in */expected/*.json are written by
// hand from what each fixture is meant to contain — never generated by the parser under test.
// Run: bun run --filter @agentic-analytics/fixtures build
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { textPdf, zipStored } from "@agentic-analytics/eval-datasets";
import * as XLSX from "xlsx";

const root = import.meta.dirname;
const enc = new TextEncoder();
type Value = string | number | boolean | null | { date: string; z?: string } | { f: string; v?: number };
interface SheetDef {
  readonly name: string;
  readonly rows: Value[][];
  readonly origin?: string; // top-left cell, default A1
  readonly merges?: string[];
  readonly hidden?: boolean;
}

const EPOCH = Date.UTC(1899, 11, 30);
const serial = (iso: string) => (Date.parse(`${iso}T00:00:00Z`) - EPOCH) / 86_400_000;

function sheet(def: SheetDef): XLSX.WorkSheet {
  const ws: XLSX.WorkSheet = {};
  const o = XLSX.utils.decode_cell(def.origin ?? "A1");
  let maxR = o.r;
  let maxC = o.c;
  for (const [i, row] of def.rows.entries()) {
    for (const [j, v] of row.entries()) {
      if (v === null) continue;
      const ref = XLSX.utils.encode_cell({ r: o.r + i, c: o.c + j });
      maxR = Math.max(maxR, o.r + i);
      maxC = Math.max(maxC, o.c + j);
      if (typeof v === "object" && "date" in v) ws[ref] = { t: "n", v: serial(v.date), z: v.z ?? "yyyy-mm-dd" };
      else if (typeof v === "object" && "f" in v) ws[ref] = v.v === undefined ? { t: "n", f: v.f } : { t: "n", f: v.f, v: v.v };
      else if (typeof v === "number") ws[ref] = { t: "n", v };
      else if (typeof v === "boolean") ws[ref] = { t: "b", v };
      else ws[ref] = { t: "s", v };
    }
  }
  ws["!ref"] = XLSX.utils.encode_range({ s: { r: 0, c: 0 }, e: { r: maxR, c: maxC } });
  if (def.merges) ws["!merges"] = def.merges.map((m) => XLSX.utils.decode_range(m));
  return ws;
}

function workbook(sheets: SheetDef[], bookType: "xlsx" | "biff8" = "xlsx"): Uint8Array {
  const wb = XLSX.utils.book_new();
  wb.Props = { Title: "fixture", CreatedDate: new Date(Date.UTC(2026, 0, 1)) };
  for (const s of sheets) XLSX.utils.book_append_sheet(wb, sheet(s), s.name);
  wb.Workbook = { Sheets: sheets.map((s) => ({ name: s.name, Hidden: s.hidden ? 1 : 0 })) };
  return XLSX.write(wb, { type: "buffer", bookType, compression: bookType === "xlsx" }) as Uint8Array;
}

