function docx(blocks: [string, string][]): Uint8Array {
  const style = (t: string) => (t === "h1" ? "Heading1" : t === "h2" ? "Heading2" : t === "li" ? "ListParagraph" : "");
  const body = blocks
    .map(([t, text]) => {
      const s = style(t);
      const numPr = t === "li" ? '<w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr>' : "";
      return `<w:p>${s || numPr ? `<w:pPr>${s ? `<w:pStyle w:val="${s}"/>` : ""}${numPr}</w:pPr>` : ""}<w:r><w:t xml:space="preserve">${text}</w:t></w:r></w:p>`;
    })
    .join("");
  const ns = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"';
  const files = {
    "[Content_Types].xml": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`,
    "_rels/.rels": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`,
    "word/document.xml": `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document ${ns}><w:body>${body}</w:body></w:document>`,
  };
  return zipStored(Object.entries(files).map(([name, s]) => ({ name, data: enc.encode(s) })));
}

function emailWithAttachment(): Uint8Array {
  const csv = "sku,qty\nBEAN-1KG,4\nCUP-12OZ,100\nLID-12OZ,100\n";
  const b64 = btoa(csv).replace(/.{76}/g, "$&\r\n");
  return enc.encode(
    [
      "From: Buyer <buyer@hotel.example>",
      "To: orders@roaster.example",
      "Subject: Revised order",
      "Date: Mon, 13 Apr 2026 10:00:00 +0500",
      "MIME-Version: 1.0",
      'Content-Type: multipart/mixed; boundary="b1"',
      "",
      "--b1",
      "Content-Type: text/plain; charset=utf-8",
      "",
      "Please see the revised quantities attached.",
      "",
      "--b1",
      'Content-Type: text/csv; name="order.csv"',
      'Content-Disposition: attachment; filename="order.csv"',
      "Content-Transfer-Encoding: base64",
      "",
      b64,
      "--b1--",
      "",
    ].join("\r\n"),
  );
}

/** A PDF whose Standard security handler rejects the empty user password, so readers ask for one. */
function protectedPdf(): Uint8Array {
  const base = new TextDecoder().decode(textPdf([["secret"]]));
  const o = "A".repeat(64);
  const u = "B".repeat(64);
  const withEncrypt = base.replace(
    /trailer\n<< \/Size (\d+) \/Root (\d+) 0 R >>/,
    (_m, size: string, rootObj: string) =>
      `trailer\n<< /Size ${size} /Root ${rootObj} 0 R /Encrypt << /Filter /Standard /V 1 /R 2 /O <${o}> /U <${u}> /P -4 >> /ID [<0123456789ABCDEF0123456789ABCDEF> <0123456789ABCDEF0123456789ABCDEF>] >>`,
  );
  return enc.encode(withEncrypt);
}
